            [ 'Using CAGR to compare a stock, a fund, and a business', '<p>Because CAGR reduces any growth story to a single annualized number, it lets you fairly compare wildly different things on the same footing — a stock\'s price appreciation, a mutual fund\'s net asset value, or a small business\'s revenue growth — as long as you\'re comparing it over the same length of time. This cross-category comparability is one of CAGR\'s most practical uses beyond simple investment returns.</p>' ],
            [ 'Why a short time period can produce a misleadingly high CAGR', '<p>CAGR calculated over just 1 or 2 years can be dramatically skewed by a single lucky or unlucky period — an investment that happened to double in one unusually strong year will show an eye-catching CAGR that says little about its typical performance. Longer measurement periods (5-10+ years) generally give a more representative picture, smoothing out single-period noise.</p>' ],
            [ 'Forward-looking use: setting a target CAGR for a goal', '<p>CAGR also works in reverse as a planning tool — if you know your starting amount, your goal amount, and your timeline, you can solve for the CAGR you\'d need to get there, which tells you how aggressive (or realistic) your investment choices need to be. A required CAGR far above typical historical market returns is usually a signal to either extend the timeline, increase contributions, or adjust the goal rather than seek out riskier investments to chase an unrealistic number.</p>' ],
        ],
        'terms'     => [ [ 'CAGR', 'Compound annual growth rate, the steady yearly rate that links a start and end value.' ], [ 'Money multiple', 'Ending value divided by starting value.' ], [ 'Absolute return', 'The plain dollar gain or loss.' ], [ 'Total return', 'An investment\'s price change plus any dividends or distributions received, combined into one figure.' ] ],
        'faqs'      => [
            [ 'How do you calculate CAGR?', 'Divide the ending value by the beginning value, raise the result to the power of one divided by the number of years, then subtract 1.' ],
